using System.ComponentModel.DataAnnotations;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.EntityFrameworkCore;
using Spilton.Api.Chat;
using Spilton.Api.Data;
using Spilton.Api.Preparation;
namespace Spilton.Api.Mocks;
public sealed record PracticeRequest(Guid? SpaceId,Guid ExamStageId,[Range(1,50)]int Count=5,Guid? SubjectId=null,Guid? TopicId=null,[StringLength(12)]string? Difficulty=null,bool WeakAreas=false,[Range(15,7200)]int DurationSeconds=600,[Range(.01,20)]decimal MarksCorrect=2,[Range(0,20)]decimal NegativeMarks=.5m,bool FloorAtZero=false);
public sealed record StartAttemptRequest(Guid? SpaceId,Guid StartKey);
public sealed record AnswerRequest(Guid? OptionId,bool MarkedForReview,[Range(0,int.MaxValue)]int Version);
public sealed record TutorRequest(Guid QuestionId,[StringLength(16)]string Style="preferred");
public sealed record QuestionRequest(Guid? SpaceId,Guid TopicId,[Required,StringLength(3000)]string Text,[Required,MinLength(4),MaxLength(4)]string[] Options,[Range(0,3)]int CorrectOptionIndex,[Required,StringLength(3000)]string Explanation,[StringLength(12)]string Difficulty="EASY",[MaxLength(5)]Guid[]? SourceChunkIds=null,bool Reviewed=false);
[ApiController,Authorize(Roles="User"),Route("api/mocks"),RequestSizeLimit(14000),ResponseCache(NoStore=true,Location=ResponseCacheLocation.None)]
public sealed class MockController(AppDbContext db,ScopeGuard scopes,AttemptService attempts):ControllerBase
{
 Guid UserId=>Guid.Parse(User.FindFirst("sub")!.Value);
 IQueryable<Question> Pool(Guid? space)=>db.Questions.Where(q=>q.UserId==null||(q.UserId==UserId&&q.SpaceId==space));
 IQueryable<MockTest> Tests(Guid? space)=>db.MockTests.Where(t=>t.UserId==null||(t.UserId==UserId&&t.SpaceId==space));
 [HttpGet("catalog")]
 public async Task<IActionResult> Catalog([FromQuery]Guid? spaceId,CancellationToken ct){if(!await scopes.Allowed(UserId,spaceId,false,ct))return NotFound();var bank=await Pool(spaceId).GroupBy(q=>new{q.TopicId,q.Topic.Name,subject=q.Topic.Subject.Name,q.Topic.SubjectId,q.Topic.Subject.ExamStageId,q.Difficulty}).Select(g=>new{g.Key.TopicId,g.Key.Name,g.Key.subject,g.Key.SubjectId,g.Key.ExamStageId,g.Key.Difficulty,count=g.Count()}).ToListAsync(ct);var tests=await Tests(spaceId).OrderByDescending(t=>t.CreatedAt).Take(100).Select(t=>new{t.Id,t.Title,t.Description,t.ExamStageId,t.DurationSeconds,t.FloorAtZero,count=t.Questions.Count,sections=t.Sections.OrderBy(s=>s.Position).Select(s=>new{s.Name,s.MarksCorrect,s.NegativeMarks}),t.NavigationRule}).ToListAsync(ct);return Ok(new{bank,tests,topics=await db.Topics.Select(t=>new{t.Id,t.Name,t.SubjectId,subject=t.Subject.Name,t.Subject.ExamStageId}).ToListAsync(ct),notice="Starter questions are original development practice, not official PYQs. Counts reflect the actual available bank. Only free section navigation is supported."});}
 [HttpPost("practice"),EnableRateLimiting("library")]
 public async Task<IActionResult> Practice(PracticeRequest request,CancellationToken ct){if(!await scopes.Allowed(UserId,request.SpaceId,true,ct))return NotFound();var query=Pool(request.SpaceId).Include(q=>q.Topic).ThenInclude(t=>t.Subject).Where(q=>q.Topic.Subject.ExamStageId==request.ExamStageId);if(request.SubjectId.HasValue)query=query.Where(q=>q.Topic.SubjectId==request.SubjectId);if(request.TopicId.HasValue)query=query.Where(q=>q.TopicId==request.TopicId);if(request.Difficulty is not null)query=query.Where(q=>q.Difficulty==request.Difficulty);var pool=await query.Take(500).ToListAsync(ct);if(pool.Count<request.Count)return BadRequest(new{title=$"Only {pool.Count} matching questions are available. Reduce the count or change filters."});
  string reason="Selected from the actual matching question bank.";
  if(request.WeakAreas){var progress=await db.UserTopicProgress.Where(p=>p.UserExamProfile.UserId==UserId&&p.UserExamProfile.SpaceId==request.SpaceId&&p.UserExamProfile.ExamStageId==request.ExamStageId).ToListAsync(ct);var mistakes=await db.AttemptAnswers.Where(a=>a.MockAttempt.UserId==UserId&&a.MockAttempt.SpaceId==request.SpaceId&&a.MockAttempt.Status=="SUBMITTED"&&a.IsCorrect==false).OrderByDescending(a=>a.MockAttempt.CompletedAt).Take(100).Select(a=>a.QuestionId).ToListAsync(ct);pool=pool.OrderByDescending(q=>mistakes.Contains(q.Id)?100:0).ThenBy(q=>{var p=progress.FirstOrDefault(p=>p.TopicId==q.TopicId);return p is {QuestionsAttempted:>0}?100.0*p.QuestionsCorrect/p.QuestionsAttempted:101;}).ThenBy(q=>progress.FirstOrDefault(p=>p.TopicId==q.TopicId)?.LastPracticedAt).ThenBy(q=>q.Id).ToList();reason="Rules-based selection: recent wrong answers first, then lower recorded topic accuracy, then least-recent practice. Under five answers is limited evidence; no ML is used.";}else pool=pool.OrderBy(_=>Guid.NewGuid()).ToList();
  var test=await Build(request,pool.Take(request.Count).ToList(),request.WeakAreas?"Weak-area practice":"Custom practice",reason,ct);return Created($"/api/mocks/tests/{test.Id}",new{test.Id,test.Title,count=test.Questions.Count,reason});}
 async Task<MockTest> Build(PracticeRequest r,List<Question> questions,string title,string description,CancellationToken ct){if(await db.MockTests.CountAsync(t=>t.UserId==UserId,ct)>=200)throw new MockException(409,"Development limit: 200 private practice configurations.");if(!await db.ExamStages.AnyAsync(s=>s.Id==r.ExamStageId,ct))throw new MockException(400,"Unknown exam stage.");var test=new MockTest{UserId=UserId,SpaceId=r.SpaceId,ExamStageId=r.ExamStageId,Title=title[..Math.Min(title.Length,200)],Description=description,DurationSeconds=r.DurationSeconds,FloorAtZero=r.FloorAtZero};var i=0;foreach(var group in questions.GroupBy(q=>q.Topic.SubjectId)){var section=new MockSection{SubjectId=group.Key,Name=group.First().Topic.Subject.Name,Position=test.Sections.Count,MarksCorrect=r.MarksCorrect,NegativeMarks=r.NegativeMarks};test.Sections.Add(section);foreach(var q in group)test.Questions.Add(new(){QuestionId=q.Id,MockSection=section,Position=i++});}db.MockTests.Add(test);await db.SaveChangesAsync(ct);return test;}

 [HttpPost("tests/{testId:guid}/attempts"),EnableRateLimiting("library")]
 public async Task<IActionResult> Start(Guid testId,StartAttemptRequest r,CancellationToken ct){if(r.StartKey==Guid.Empty)return BadRequest(new{title="A start request identifier is required."});if(!await scopes.Allowed(UserId,r.SpaceId,true,ct))return NotFound();await using var gate=await ConversationLock.TryAcquire(db,UserId,ct);if(gate is null)return Conflict(new{title="Another change is being saved. Retry shortly."});var existing=await db.MockAttempts.FirstOrDefaultAsync(a=>a.UserId==UserId&&a.StartKey==r.StartKey,ct);if(existing is not null){if(existing.MockTestId!=testId||existing.SpaceId!=r.SpaceId)return Conflict(new{title="Start identifier already belongs to another attempt."});return Ok(new{existing.Id});}
  var active=await db.MockAttempts.FirstOrDefaultAsync(a=>a.UserId==UserId&&a.MockTestId==testId&&a.SpaceId==r.SpaceId&&a.Status=="ACTIVE",ct);if(active is not null)return Ok(new{active.Id});
  var test=await Tests(r.SpaceId).Include(t=>t.Questions).ThenInclude(q=>q.MockSection).SingleOrDefaultAsync(t=>t.Id==testId,ct);if(test is null)return NotFound();var profile=await db.UserExamProfiles.SingleOrDefaultAsync(p=>p.UserId==UserId&&p.SpaceId==r.SpaceId,ct);if(profile is not null&&profile.ExamStageId!=test.ExamStageId)return Conflict(new{title="Your current Space targets another exam stage. Change its exam profile or choose another Space."});if(profile is null){profile=new(){UserId=UserId,SpaceId=r.SpaceId,ExamStageId=test.ExamStageId};db.UserExamProfiles.Add(profile);}
  var now=attempts.Now;var a=new MockAttempt{UserId=UserId,SpaceId=r.SpaceId,MockTestId=testId,UserExamProfile=profile,StartKey=r.StartKey,StartedAt=now,ExpiresAt=now.AddSeconds(test.DurationSeconds)};a.Answers=test.Questions.Select(q=>new AttemptAnswer{QuestionId=q.QuestionId,MarksCorrect=q.MockSection.MarksCorrect,NegativeMarks=q.MockSection.NegativeMarks}).ToList();db.MockAttempts.Add(a);await db.SaveChangesAsync(ct);return Created($"/api/mocks/attempts/{a.Id}",new{a.Id});}
 [HttpGet("attempts/{id:guid}")]
 public async Task<IActionResult> GetAttempt(Guid id,CancellationToken ct){await attempts.Expire(UserId,id,ct);var a=await attempts.Load(UserId,id,ct);return a is null?NotFound():Ok(attempts.View(a));}
 [HttpPatch("attempts/{id:guid}/answers/{questionId:guid}"),EnableRateLimiting("mockAnswers")]
 public async Task<IActionResult> Answer(Guid id,Guid questionId,AnswerRequest r,CancellationToken ct){if(!await db.MockAttempts.AnyAsync(a=>a.Id==id&&a.UserId==UserId,ct))return NotFound();await using var gate=await ConversationLock.TryAcquire(db,id,ct);if(gate is null)return Conflict(new{title="An answer or submission is being saved. Reload and retry."});var a=await attempts.Load(UserId,id,ct);if(a is null)return NotFound();if(a.Status!="ACTIVE")return Conflict(new{title="Submitted answers cannot be changed."});if(attempts.Now>=a.ExpiresAt){await attempts.Complete(a,ct);return Conflict(new{title="Time expired. The attempt has been submitted; open its result."});}var answer=a.Answers.SingleOrDefault(x=>x.QuestionId==questionId);if(answer is null)return BadRequest(new{title="Question does not belong to this attempt."});if(r.OptionId.HasValue&&!answer.Question.Options.Any(o=>o.Id==r.OptionId))return BadRequest(new{title="Option does not belong to this question."});if(answer.Version!=r.Version)return Conflict(new{title="This answer changed in another tab. Reload the attempt before editing."});answer.OptionId=r.OptionId;answer.MarkedForReview=r.MarkedForReview;answer.Visited=true;answer.Version++;await db.SaveChangesAsync(ct);return Ok(attempts.View(a));}
 [HttpPost("attempts/{id:guid}/submit"),EnableRateLimiting("library")]
 public async Task<IActionResult> Submit(Guid id,CancellationToken ct){if(!await db.MockAttempts.AnyAsync(a=>a.Id==id&&a.UserId==UserId,ct))return NotFound();await using var gate=await ConversationLock.TryAcquire(db,id,ct);if(gate is null)return Conflict(new{title="A save is in progress. Retry submission shortly."});var a=await attempts.Load(UserId,id,ct);if(a is null)return NotFound();await attempts.Complete(a,ct);return Ok(attempts.View(a));}
 [HttpGet("attempts")]
 public async Task<IActionResult> History([FromQuery]Guid? spaceId,CancellationToken ct){if(!await scopes.Allowed(UserId,spaceId,false,ct))return NotFound();var expired=await db.MockAttempts.Where(a=>a.UserId==UserId&&a.SpaceId==spaceId&&a.Status=="ACTIVE"&&a.ExpiresAt<=attempts.Now).Select(a=>a.Id).Take(10).ToListAsync(ct);foreach(var id in expired)await attempts.Expire(UserId,id,ct);return Ok(new{items=await db.MockAttempts.AsNoTracking().Where(a=>a.UserId==UserId&&a.SpaceId==spaceId).OrderByDescending(a=>a.StartedAt).Take(100).Select(a=>new{a.Id,title=a.MockTest.Title,a.Status,a.StartedAt,a.ExpiresAt,score=a.Status=="SUBMITTED"?(decimal?)a.FinalScore:null,a.AccuracyPercent,a.TimeTakenSeconds}).ToListAsync(ct)});}
 [HttpPost("attempts/{id:guid}/tutor"),EnableRateLimiting("chat")]
 public async Task<IActionResult> Tutor(Guid id,TutorRequest r,CancellationToken ct){var a=await attempts.Load(UserId,id,ct);if(a is null)return NotFound();if(a.Status!="SUBMITTED")return Conflict(new{title="Submit the test before viewing explanations."});var answer=a.Answers.SingleOrDefault(x=>x.QuestionId==r.QuestionId);if(answer is null)return NotFound();if(!new[]{"preferred","simple","telugu","similar"}.Contains(r.Style))return BadRequest();var language=await db.UserExamProfiles.Where(p=>p.UserId==UserId&&p.SpaceId==a.SpaceId).Select(p=>p.PreferredLanguage).FirstOrDefaultAsync(ct)??"English";if(r.Style=="telugu")language="Telugu";var q=answer.Question;var prompt="Tutor this completed practice question. Use the supplied correct answer and explanation; do not reveal private chain-of-thought. Give a concise student-facing explanation in "+language+". "+(r.Style=="simple"?"Use a simpler explanation and one small example.":r.Style=="similar"?"Then give one similar ORIGINAL practice question; never label it PYQ.":"")+"\n"+JsonSerializer.Serialize(new{exam=a.MockTest.ExamStage.Exam.Name,stage=a.MockTest.ExamStage.Name,topic=q.Topic.Name,question=q.Text,options=q.Options.OrderBy(o=>o.Index).Select(o=>o.Text),correct=q.Options.Single(o=>o.Index==q.CorrectOptionIndex).Text,userAnswer=q.Options.FirstOrDefault(o=>o.Id==answer.OptionId)?.Text??"Unanswered",explanation=q.Explanation,sourceType=q.SourceType});return Ok(new{spaceId=a.SpaceId,prompt});}

 [HttpPost("questions"),EnableRateLimiting("library")]
 public Task<IActionResult> CreateQuestion(QuestionRequest r,CancellationToken ct)=>SaveQuestion(r,null,ct);
 [HttpPost("papers/{id:guid}/questions"),EnableRateLimiting("library")]
 public Task<IActionResult> ReviewPaperQuestion(Guid id,QuestionRequest r,CancellationToken ct)=>SaveQuestion(r,id,ct);
 async Task<IActionResult> SaveQuestion(QuestionRequest r,Guid? paper,CancellationToken ct){if(!await scopes.Allowed(UserId,r.SpaceId,true,ct))return NotFound();if(!r.Reviewed||r.Options.Any(o=>string.IsNullOrWhiteSpace(o)||o.Length>1000)||r.Options.Select(o=>o.Trim()).Distinct().Count()!=4||!new[]{"EASY","MEDIUM","HARD"}.Contains(r.Difficulty))return BadRequest(new{title="Review the question, four distinct nonempty options, answer and explanation before saving."});if(!await db.Topics.AnyAsync(t=>t.Id==r.TopicId,ct))return BadRequest(new{title="Choose a catalog topic."});if(await db.Questions.CountAsync(q=>q.UserId==UserId,ct)>=300)return Conflict(new{title="Development limit: 300 private questions."});var q=new Question{UserId=UserId,SpaceId=r.SpaceId,TopicId=r.TopicId,Text=r.Text.Trim(),Explanation=r.Explanation.Trim(),CorrectOptionIndex=r.CorrectOptionIndex,Difficulty=r.Difficulty,SourceType="USER_AUTHORED"};
  if(paper.HasValue){var source=await db.GovernmentResources.Include(s=>s.Document).SingleOrDefaultAsync(s=>s.Id==paper&&s.UserId==UserId&&s.SpaceId==r.SpaceId&&s.Kind=="PYQ"&&s.Document!=null&&s.Document.Status=="READY"&&s.Document.SpaceId==r.SpaceId,ct);if(source is null)return NotFound();if(r.SourceChunkIds is not {Length:>0})return BadRequest(new{title="Select source chunk IDs for the extracted question and options."});var chunks=await db.DocumentChunks.Where(c=>c.DocumentId==source.DocumentId&&r.SourceChunkIds.Contains(c.Id)).OrderBy(c=>c.ChunkIndex).ToListAsync(ct);if(chunks.Count!=r.SourceChunkIds.Distinct().Count())return BadRequest(new{title="Source chunks are unavailable."});string Normalize(string s)=>Regex.Replace(s,@"\s+"," ").Trim();var text=Normalize(string.Join(" ",chunks.Select(c=>c.Content)));if(!text.Contains(Normalize(q.Text),StringComparison.Ordinal))return BadRequest(new{title="Question text must match the actual extracted source."});for(var i=0;i<4;i++){var letter=(char)('A'+i);if(!Regex.IsMatch(text,@"(?:\("+letter+@"\)|\b"+letter+@"[.)])\s*"+Regex.Escape(Normalize(r.Options[i])),RegexOptions.IgnoreCase))return BadRequest(new{title="All four labelled options must appear in the extracted source. Incomplete extraction cannot become a mock."});}q.SourceResourceId=source.Id;q.SourceType="USER_REVIEWED_PAPER";q.SourceMetadataJson=JsonSerializer.Serialize(new{source.Title,source.SourceUrl,source.SourceType,source.Verification,source.ExamId,source.Year,source.Stage,source.Shift,source.Language,source.DocumentId,chunks=chunks.Select(c=>new{c.Id,c.PageNumber,c.Section}),answerKey="Manually reviewed; not automatically verified",metadata="Original source labels retained; missing year/shift is unknown"});if(await db.Questions.AnyAsync(x=>x.UserId==UserId&&x.SourceResourceId==source.Id&&x.Text==q.Text,ct))return Conflict(new{title="This question is already reviewed."});}
  q.Options=r.Options.Select((o,i)=>new QuestionOption{Index=i,Text=o.Trim()}).ToList();db.Questions.Add(q);await db.SaveChangesAsync(ct);return Created($"/api/mocks/questions/{q.Id}",new{q.Id,q.SourceType});}
 [HttpGet("papers/{id:guid}/status")]
 public async Task<IActionResult> PaperStatus(Guid id,CancellationToken ct){var paper=await db.GovernmentResources.SingleOrDefaultAsync(r=>r.Id==id&&r.UserId==UserId&&r.Kind=="PYQ",ct);if(paper is null)return NotFound();var count=await db.Questions.CountAsync(q=>q.UserId==UserId&&q.SourceResourceId==id&&q.SpaceId==paper.SpaceId,ct);var chunks=await db.DocumentChunks.Where(c=>c.DocumentId==paper.DocumentId&&c.Document.UserId==UserId&&c.Document.Status=="READY"&&c.Document.SpaceId==paper.SpaceId).OrderBy(c=>c.ChunkIndex).Take(50).Select(c=>new{c.Id,c.Content,c.PageNumber}).ToListAsync(ct);return Ok(new{paper.Id,paper.Title,paper.SpaceId,reviewedCount=count,canConvert=count>0&&chunks.Count>0,reason=count==0?"No complete, reviewed four-option questions with a checked answer key. Review extracted source text before conversion.":"Conversion uses only manually reviewed complete questions; source metadata and manual answer-key status are retained.",chunks});}
 [HttpPost("papers/{id:guid}/convert"),EnableRateLimiting("library")]
 public async Task<IActionResult> ConvertPaper(Guid id,PracticeRequest r,CancellationToken ct){if(!await scopes.Allowed(UserId,r.SpaceId,true,ct))return NotFound();var paper=await db.GovernmentResources.SingleOrDefaultAsync(p=>p.Id==id&&p.UserId==UserId&&p.SpaceId==r.SpaceId&&p.Kind=="PYQ"&&p.Document!=null&&p.Document.Status=="READY"&&p.Document.SpaceId==r.SpaceId,ct);if(paper is null)return NotFound();var questions=await Pool(r.SpaceId).Include(q=>q.Topic).ThenInclude(t=>t.Subject).Where(q=>q.SourceResourceId==id&&q.Topic.Subject.ExamStageId==r.ExamStageId).OrderBy(q=>q.Id).ToListAsync(ct);if(questions.Count<r.Count)return BadRequest(new{title=$"Only {questions.Count} complete reviewed questions match this stage. Incomplete extraction cannot be converted."});var test=await Build(r,questions.Take(r.Count).ToList(),paper.Title+" · reviewed practice","Selected reviewed paper questions. Answer keys are manually checked; source metadata may be incomplete.",ct);return Created($"/api/mocks/tests/{test.Id}",new{test.Id,test.Title,count=test.Questions.Count});}
}
